import{_ as o,l as r,o as t,c as n,v as e,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"照明均匀性与狭缝","description":"","frontmatter":{"title":"照明均匀性与狭缝","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/illumination-uniformity-slit.md","filePath":"litho/illumination-uniformity-slit.md","lastUpdated":1789023840000}'),m={name:"litho/illumination-uniformity-slit.md"};function _(c,a,u,f,E,A){const l=r("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="照明均匀性与狭缝" tabindex="-1">照明均匀性与狭缝 <a class="header-anchor" href="#照明均匀性与狭缝" aria-label="Permalink to &quot;照明均匀性与狭缝&quot;">​</a></h1><div class="epigraph"><p>扫描把狭缝里的不均匀平均掉一部分；狭缝长度方向的不均匀会原样印进场。均匀性要沿狭缝报，不能只报中心点。</p><footer>—— 对照 [狭缝与扫描平均](/litho/slit-scan-average)；剂量均匀性实践</footer></div><p><a href="/litho/reticle-masking-blades">上一课</a>张开场。缺口是狭缝内强度 \\(I(x)\\)：扫描方向会被平均，垂直扫描的狭缝长轴不会。本课钉这件事，不重写双工件台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复眼之后仍有残纹和偏振相关透过。扫描平均降低扫描向高频，但狭缝两端若暗，整场对应位置永远欠剂量。CDU 地图呈「沿狭缝的条」时，先查照明，再查热板。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用剂量传感器或晶圆上剂量垫沿狭缝采样。补偿：照明微调、扫描速度调制、光学元件操纵。规格用峰值–谷值或标准差相对平均剂量。换光瞳形状（偶极 vs 环）会改均匀性，要分别标定。</p>',7)),(t(),s(p,null,{default:i(()=>[h(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLIT%5B%22%E7%8B%AD%E7%BC%9D%20I(x)%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%E5%B9%B3%E5%9D%87%22%5D%0A%20%20SLIT%20--%3E%20FIELD%5B%22%E5%9C%BA%E5%86%85%E5%9B%BA%E5%AE%9A%E6%9D%A1%E7%BA%B9%22%5D%0A%20%20FIELD%20--%3E%20CDU%5B%22CD%20%E6%9D%A1%E5%B8%A6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p><span class="marginnote">偏振照明下，复眼通道透过率可能随偏振变，均匀性与 <a href="/litho/illuminator-polarization">照明偏振</a> 耦合。不要只在自然光下验光。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扫描是时间积分。扫描向的 \\(I(y)\\) 被狭缝宽度卷积；狭缝长向 \\(I(x)\\) 没有这段卷积。所以「均光很好」必须声明沿哪一轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课光瞳测量：均匀性是场，光瞳是角谱。两套计量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>狭缝长向不均匀直接进场 CDU。</li><li>扫描只平均扫描向。换光瞳要重新测均匀性。</li><li>出处：狭缝课；剂量均匀性实践。</li></ul>',7))])}const T=o(m,[["render",_]]);export{B as __pageData,T as default};
